INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 0, 10, 0, 1, 'You are not interested in my gift? Well then let us see how much amber survived the ritual.'), (@e, 1, 10, 0, 1, 'Had you brought me Deru Heartwood Sap, I could have grown this into something greater.'), (@e, 2, 67, 0, 1, 'refundAmber');
INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest) VALUES (53271, 1, 1, 900863, 'ViridianTradeUp-sapfirst');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 0, 12, 0, 1, NULL), (@e, 1, 10, 0, 1, 'Keep the sap in your pack, champion, and hand me the Stormwood weapon itself. I will draw the sap into it.');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) SELECT e.id, (SELECT MAX(a.`order`) + 1 FROM weenie_properties_emote_action a WHERE a.emote_Id = e.id), 10, 0, 1, 'If you carry Deru Heartwood Sap, hand me any Stormwood weapon and I will grow it into its Viridian kin.' FROM weenie_properties_emote e WHERE e.object_Id = 53271 AND e.category = 7;
